(function () {
  var container = document.getElementById('container');
  var canvas = document.createElement('canvas');
  canvas.style.width = '100%';
  canvas.style.height = '100%';
  canvas.style.display = 'block';
  container.appendChild(canvas);

  var state = {
    notationView: 'Theta',
    thresholdN0: 3,
    constantMultiplier: 1.5
  };
  var hoveredPanel = null;

  var steps = [
    {
      title: 'Two-sided Θ bound',
      narration: 'In the Θ view, f(n) must eventually stay inside a corridor between c1 g(n) and c2 g(n). Early crossings do not matter if they occur before n0.',
      state: { notationView: 'Theta', thresholdN0: 3, constantMultiplier: 1.5 }
    },
    {
      title: 'Move the threshold',
      narration: 'Drag n0 to the right and notice that violations before the dashed line disappear from consideration. If a violation remains to the right of n0, the chosen threshold is not large enough.',
      state: { notationView: 'Theta', thresholdN0: 5, constantMultiplier: 1.5 }
    },
    {
      title: 'Adjust the constant factor',
      narration: 'Changing the multiplier raises or lowers the scaled copy of g(n). A valid asymptotic bound often appears only after choosing a large enough positive constant.',
      state: { notationView: 'O', thresholdN0: 3, constantMultiplier: 1.2 }
    },
    {
      title: 'Upper-only O bound',
      narration: 'In the O view, only the region below c g(n) matters after n0. f(n) may be much smaller than the bound; O does not require a matching lower bound.',
      state: { notationView: 'O', thresholdN0: 3, constantMultiplier: 1.8 }
    },
    {
      title: 'Lower-only Ω bound',
      narration: 'In the Ω view, the allowed region is above c g(n) after n0. This is the mirror idea of O: f(n) must eventually be at least a constant multiple of g(n).',
      state: { notationView: 'Omega', thresholdN0: 3, constantMultiplier: 1.2 }
    }
  ];
  var currentStep = 0;
  var lastPanels = [];

  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

  function gBase(x) {
    return 0.78 + 0.33 * x + 0.018 * x * x;
  }

  function thetaLower(x) {
    return (0.62 * state.constantMultiplier) * gBase(x);
  }

  function thetaUpper(x) {
    return (1.26 * state.constantMultiplier) * gBase(x);
  }

  function thetaF(x) {
    var early = 1.55 * Math.sin(2.7 * x - 0.8) * Math.exp(-0.19 * Math.pow(x - 2.0, 2));
    var bump = 1.15 * Math.exp(-0.55 * Math.pow(x - 6.0, 2));
    return 1.18 * gBase(x) + early + bump;
  }

  function oUpper(x) {
    return state.constantMultiplier * (0.72 + 0.26 * x + 0.041 * x * x);
  }

  function oF(x) {
    var gg = 0.72 + 0.26 * x + 0.041 * x * x;
    var early = -1.5 * Math.exp(-0.9 * Math.pow(x - 1.1, 2)) + 2.45 * Math.exp(-1.25 * Math.pow(x - 2.25, 2)) - 1.2 * Math.exp(-0.55 * Math.pow(x - 4.1, 2));
    return 1.32 * gg + early;
  }

  function omegaLower(x) {
    return state.constantMultiplier * (0.9 + 0.21 * x + 0.018 * x * x);
  }

  function omegaF(x) {
    var gg = 0.9 + 0.21 * x + 0.018 * x * x;
    var early = 1.25 * Math.sin(3.3 * x - 0.5) * Math.exp(-0.24 * Math.pow(x - 1.7, 2)) - 0.65 * Math.exp(-0.65 * Math.pow(x - 3.8, 2));
    return 1.55 * gg + early + 0.22 * x;
  }

  function makePanelGeometry(area, idx) {
    var W = area.width, H = area.height;
    var gap = W * 0.07;
    var pw = (W - 2 * gap) / 3;
    var left = area.left + idx * (pw + gap);
    var top = area.top + H * 0.035;
    var bottomPad = H * 0.21;
    return {
      left: left,
      top: top,
      width: pw,
      height: H - bottomPad,
      bottom: top + H - bottomPad,
      xMin: 0,
      xMax: 10,
      yMin: 0,
      yMax: 11.2
    };
  }

  function sx(p, x) {
    return p.left + (x - p.xMin) / (p.xMax - p.xMin) * p.width;
  }

  function sy(p, y) {
    return p.bottom - (y - p.yMin) / (p.yMax - p.yMin) * p.height;
  }

  function drawArrow(ctx, x1, y1, x2, y2, color, lw, scale) {
    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = lw;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
    var a = Math.atan2(y2 - y1, x2 - x1);
    var len = 0.018 * scale;
    ctx.beginPath();
    ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - len * Math.cos(a - Math.PI / 7), y2 - len * Math.sin(a - Math.PI / 7));
    ctx.lineTo(x2 - len * Math.cos(a + Math.PI / 7), y2 - len * Math.sin(a + Math.PI / 7));
    ctx.closePath();
    ctx.fill();
  }

  function strokeCurve(ctx, p, fn, color, lw, scale) {
    ctx.strokeStyle = color;
    ctx.lineWidth = lw;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    for (var i = 0; i <= 220; i++) {
      var x = p.xMin + (p.xMax - p.xMin) * i / 220;
      var y = clamp(fn(x), -1, 13);
      var px = sx(p, x), py = sy(p, y);
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();
  }

  function fillAllowed(ctx, p, kind) {
    var x0 = state.thresholdN0;
    ctx.fillStyle = 'rgba(99, 178, 122, 0.20)';
    ctx.beginPath();

    if (kind === 'Theta') {
      for (var i = 0; i <= 160; i++) {
        var x = x0 + (10 - x0) * i / 160;
        var up = thetaUpper(x);
        if (i === 0) ctx.moveTo(sx(p, x), sy(p, up));
        else ctx.lineTo(sx(p, x), sy(p, up));
      }
      for (var j = 160; j >= 0; j--) {
        var xb = x0 + (10 - x0) * j / 160;
        ctx.lineTo(sx(p, xb), sy(p, thetaLower(xb)));
      }
    } else if (kind === 'O') {
      ctx.moveTo(sx(p, x0), sy(p, 0));
      for (var k = 0; k <= 160; k++) {
        var xo = x0 + (10 - x0) * k / 160;
        ctx.lineTo(sx(p, xo), sy(p, oUpper(xo)));
      }
      ctx.lineTo(sx(p, 10), sy(p, 0));
    } else {
      for (var m = 0; m <= 160; m++) {
        var xm = x0 + (10 - x0) * m / 160;
        var lo = omegaLower(xm);
        if (m === 0) ctx.moveTo(sx(p, xm), sy(p, lo));
        else ctx.lineTo(sx(p, xm), sy(p, lo));
      }
      ctx.lineTo(sx(p, 10), sy(p, p.yMax));
      ctx.lineTo(sx(p, x0), sy(p, p.yMax));
    }
    ctx.closePath();
    ctx.fill();
  }

  function drawViolations(ctx, p, kind, scale) {
    ctx.strokeStyle = '#c92525';
    ctx.fillStyle = '#c92525';
    ctx.lineWidth = Math.max(1.1, scale * 0.0022);
    var r = Math.max(2, scale * 0.0052);
    var count = 0;

    for (var i = 0; i <= 56; i++) {
      var x = state.thresholdN0 + (10 - state.thresholdN0) * i / 56;
      var y, bad = false;
      if (kind === 'Theta') {
        y = thetaF(x);
        bad = y < thetaLower(x) || y > thetaUpper(x);
      } else if (kind === 'O') {
        y = oF(x);
        bad = y > oUpper(x);
      } else {
        y = omegaF(x);
        bad = y < omegaLower(x);
      }
      if (bad) {
        count++;
        var px = sx(p, x), py = sy(p, y);
        ctx.beginPath();
        ctx.moveTo(px - r, py - r);
        ctx.lineTo(px + r, py + r);
        ctx.moveTo(px + r, py - r);
        ctx.lineTo(px - r, py + r);
        ctx.stroke();
      }
    }
    return count;
  }

  function textHalo(ctx, txt, x, y, font, align, baseline, fill) {
    ctx.font = font;
    ctx.textAlign = align || 'left';
    ctx.textBaseline = baseline || 'alphabetic';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 4;
    ctx.strokeText(txt, x, y);
    ctx.fillStyle = fill || '#000';
    ctx.fillText(txt, x, y);
  }

  function dashedThreshold(ctx, p, scale) {
    var x = sx(p, state.thresholdN0);
    ctx.save();
    ctx.setLineDash([5, 5]);
    ctx.strokeStyle = '#111';
    ctx.lineWidth = Math.max(0.9, scale * 0.0017);
    ctx.beginPath();
    ctx.moveTo(x, p.bottom);
    ctx.lineTo(x, p.bottom - p.height * 0.43);
    ctx.stroke();
    ctx.restore();
    return x;
  }

  function drawPanel(ctx, p, kind, idx, scale) {
    var active = state.notationView === kind;
    var alpha = active ? 1 : 0.45;
    var ink = '#111111';
    ctx.save();
    ctx.globalAlpha = alpha;

    if (active) {
      fillAllowed(ctx, p, kind);
      ctx.strokeStyle = '#63b27a';
      ctx.lineWidth = Math.max(1.2, scale * 0.0022);
      ctx.strokeRect(p.left - scale * 0.01, p.top - scale * 0.012, p.width + scale * 0.02, p.height + scale * 0.11);
    }

    var lw = Math.max(1, scale * 0.0018);
    ctx.strokeStyle = ink;
    ctx.fillStyle = ink;
    ctx.lineWidth = lw;

    ctx.beginPath();
    ctx.moveTo(p.left, p.bottom);
    ctx.lineTo(p.left, p.top - scale * 0.01);
    ctx.stroke();
    drawArrow(ctx, p.left, p.bottom, p.left + p.width * 1.03, p.bottom, ink, lw, scale);

    var tx = dashedThreshold(ctx, p, scale);
    var serif = Math.max(13, scale * 0.025);
    textHalo(ctx, 'n', p.left + p.width * 1.045, p.bottom + serif * 0.22, 'italic ' + serif + 'px Georgia, serif', 'left', 'middle', ink);
    textHalo(ctx, 'n₀', tx, p.bottom + serif * 1.18, 'italic ' + serif + 'px Georgia, serif', 'center', 'middle', ink);

    if (kind === 'Theta') {
      strokeCurve(ctx, p, thetaUpper, ink, lw, scale);
      strokeCurve(ctx, p, thetaF, ink, lw, scale);
      strokeCurve(ctx, p, thetaLower, ink, lw, scale);
      textHalo(ctx, 'c₂g(n)', sx(p, 8.7), sy(p, thetaUpper(8.7)) - serif * 0.45, 'italic ' + serif + 'px Georgia, serif', 'left', 'bottom', ink);
      textHalo(ctx, 'f(n)', sx(p, 8.05), sy(p, thetaF(8.05)) - serif * 0.55, 'italic ' + serif + 'px Georgia, serif', 'left', 'bottom', ink);
      textHalo(ctx, 'c₁g(n)', sx(p, 7.6), sy(p, thetaLower(7.6)) - serif * 0.20, 'italic ' + serif + 'px Georgia, serif', 'left', 'bottom', ink);
      if (active) drawViolations(ctx, p, kind, scale);
      textHalo(ctx, 'f(n) = Θ(g(n))', p.left + p.width * 0.64, p.bottom + serif * 1.95, 'italic ' + (serif * 1.05) + 'px Georgia, serif', 'center', 'middle', ink);
      textHalo(ctx, '(a)', p.left + p.width * 0.50, p.bottom + serif * 3.12, 'bold ' + (serif * 0.95) + 'px Georgia, serif', 'center', 'middle', ink);
    } else if (kind === 'O') {
      strokeCurve(ctx, p, oUpper, ink, lw, scale);
      strokeCurve(ctx, p, oF, ink, lw, scale);
      textHalo(ctx, 'cg(n)', sx(p, 8.55), sy(p, oUpper(8.55)) - serif * 0.5, 'italic ' + serif + 'px Georgia, serif', 'left', 'bottom', ink);
      textHalo(ctx, 'f(n)', sx(p, 8.75), sy(p, oF(8.75)) - serif * 0.25, 'italic ' + serif + 'px Georgia, serif', 'left', 'bottom', ink);
      if (active) drawViolations(ctx, p, kind, scale);
      textHalo(ctx, 'f(n) = O(g(n))', p.left + p.width * 0.60, p.bottom + serif * 1.95, 'italic ' + (serif * 1.05) + 'px Georgia, serif', 'center', 'middle', ink);
      textHalo(ctx, '(b)', p.left + p.width * 0.50, p.bottom + serif * 3.12, 'bold ' + (serif * 0.95) + 'px Georgia, serif', 'center', 'middle', ink);
    } else {
