      strokeCurve(ctx, p, omegaLower, ink, lw, scale);
      textHalo(ctx, 'f(n)', sx(p, 8.9), sy(p, omegaF(8.9)) - serif * 0.35, 'italic ' + serif + 'px Georgia, serif', 'left', 'bottom', ink);
      textHalo(ctx, 'cg(n)', sx(p, 8.65), sy(p, omegaLower(8.65)) - serif * 0.18, 'italic ' + serif + 'px Georgia, serif', 'left', 'bottom', ink);
      if (active) drawViolations(ctx, p, kind, scale);
      textHalo(ctx, 'f(n) = Ω(g(n))', p.left + p.width * 0.63, p.bottom + serif * 1.95, 'italic ' + (serif * 1.05) + 'px Georgia, serif', 'center', 'middle', ink);
      textHalo(ctx, '(c)', p.left + p.width * 0.50, p.bottom + serif * 3.12, 'bold ' + (serif * 0.95) + 'px Georgia, serif', 'center', 'middle', ink);
    }
    ctx.restore();
  }

  var asymptoticPlugin = {
    id: 'asymptoticSketch',
    afterDraw: function (chart) {
      var ctx = chart.ctx;
      var W = chart.width, H = chart.height;
      var scale = Math.min(W, H);

      ctx.save();
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, W, H);

      var area = {
        left: W * 0.035,
        top: H * 0.04,
        width: W * 0.93,
        height: H * 0.89
      };

      lastPanels = [
        makePanelGeometry(area, 0),
        makePanelGeometry(area, 1),
        makePanelGeometry(area, 2)
      ];

      drawPanel(ctx, lastPanels[0], 'Theta', 0, scale);
      drawPanel(ctx, lastPanels[1], 'O', 1, scale);
      drawPanel(ctx, lastPanels[2], 'Omega', 2, scale);
      ctx.restore();
    }
  };

  var chart = new Chart(canvas.getContext('2d'), {
    type: 'scatter',
    data: { datasets: [] },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: { duration: 180 },
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      scales: {
        x: { display: false, min: 0, max: 1 },
        y: { display: false, min: 0, max: 1 }
      },
      events: []
    },
    plugins: [asymptoticPlugin]
  });
  window.__markRendered();

  function redraw() {
    chart.update('none');
  }

  window.update_notationView = function (v) {
    state.notationView = v;
    redraw();
  };

  window.update_thresholdN0 = function (v) {
    state.thresholdN0 = v;
    redraw();
  };

  window.update_constantMultiplier = function (v) {
    state.constantMultiplier = v;
    redraw();
  };

  function setControlValues(st) {
    state.notationView = st.notationView;
    state.thresholdN0 = +st.thresholdN0;
    state.constantMultiplier = +st.constantMultiplier;

    var sel = document.getElementById('notationViewInput');
    var n0 = document.getElementById('thresholdN0Input');
    var c = document.getElementById('constantMultiplierInput');
    if (sel) sel.value = state.notationView;
    if (n0) n0.value = state.thresholdN0;
    if (c) c.value = state.constantMultiplier;
    var n0v = document.getElementById('thresholdN0Val');
    var cv = document.getElementById('constantMultiplierVal');
    if (n0v) n0v.value = state.thresholdN0;
    if (cv) cv.value = state.constantMultiplier.toFixed(1).replace(/\.0$/, '');
    redraw();
  }

  function showStep(i) {
    currentStep = (i + steps.length) % steps.length;
    setControlValues(steps[currentStep].state);
    var narr = document.getElementById('demoNarration');
    var lab = document.getElementById('stepLabel');
    if (narr) narr.textContent = steps[currentStep].narration;
    if (lab) lab.textContent = (currentStep + 1) + ' / ' + steps.length;
  }

  window.prevStep = function () { showStep(currentStep - 1); };
  window.nextStep = function () { showStep(currentStep + 1); };

  canvas.addEventListener('mousemove', function (e) {
    var rect = canvas.getBoundingClientRect();
    var x = (e.clientX - rect.left) * chart.width / rect.width;
    var y = (e.clientY - rect.top) * chart.height / rect.height;
    var names = ['Θ: f(n) is eventually between c₁g(n) and c₂g(n).', 'O: f(n) is eventually below cg(n).', 'Ω: f(n) is eventually above cg(n).'];
    hoveredPanel = null;
    for (var i = 0; i < lastPanels.length; i++) {
      var p = lastPanels[i];
      if (x >= p.left && x <= p.left + p.width && y >= p.top && y <= p.bottom + p.height * 0.25) {
        hoveredPanel = i;
        break;
      }
    }
    if (hoveredPanel == null) {
      canvas.style.cursor = 'default';
      hideTooltip();
    } else {
      canvas.style.cursor = 'pointer';
      showTooltip(names[hoveredPanel] + ' The dashed line marks where the asymptotic claim starts.', e);
    }
  });

  canvas.addEventListener('mouseleave', function () {
    hoveredPanel = null;
    canvas.style.cursor = 'default';
    hideTooltip();
  });

  canvas.addEventListener('click', function () {
    if (hoveredPanel == null) return;
    var titles = ['Theta bound', 'Big-O bound', 'Big-Omega bound'];
    var bodies = [
      'Θ(g(n)) means two constants can trap f(n) above and below after n₀. The shaded corridor is the part that matters; wiggles before n₀ are ignored.',
      'O(g(n)) is an eventual upper bound. f(n) can be far below the comparison curve and still satisfy the relation.',
      'Ω(g(n)) is an eventual lower bound. After n₀, f(n) must stay at least as large as a constant multiple of g(n).'
    ];
    showPopup(titles[hoveredPanel], bodies[hoveredPanel]);
  });

  showStep(0);
})();
// @FIGURE_CODE_END

