// @FIGURE_CODE_BEGIN
(function () {
  var container = document.getElementById('container');
  var canvas = document.createElement('canvas');
  canvas.style.width = '100%';
  canvas.style.height = '100%';
  canvas.style.display = 'block';
  container.appendChild(canvas);

  var DEFAULT_C = 1.5;
  var state = {
    notationView: 'Theta',
    thresholdN0: 3,
    constantMultiplier: 1.5,
    showOverlay: false
  };

  var steps = [
    {
      title: 'Two-sided Θ bound',
      narration: 'In the Θ view, f(n) must eventually stay inside a corridor between c1 g(n) and c2 g(n). Early crossings do not matter if they occur before n0.',
      state: { notationView: 'Theta', thresholdN0: 3, constantMultiplier: 1.5, showOverlay: false }
    },
    {
      title: 'Move the threshold',
      narration: 'The dashed line is the point after which the claim is tested. The green overlay now shows the allowed part; crossings before n0 are ignored.',
      state: { notationView: 'Theta', thresholdN0: 5, constantMultiplier: 1.5, showOverlay: true }
    },
    {
      title: 'Adjust the constant factor',
      narration: 'Changing the multiplier moves a scaled copy of g(n). A larger constant can turn a failed eventual bound into a valid one.',
      state: { notationView: 'O', thresholdN0: 3, constantMultiplier: 1.2, showOverlay: true }
    },
    {
      title: 'Upper-only O bound',
      narration: 'For O(g(n)), f(n) only needs to stay below c g(n) after n0. There is no requirement that f(n) also be close from below.',
      state: { notationView: 'O', thresholdN0: 3, constantMultiplier: 1.8, showOverlay: true }
    },
    {
      title: 'Lower-only Ω bound',
      narration: 'For Ω(g(n)), the allowed region is above c g(n) after n0. This is the lower-bound mirror image of Big-O.',
      state: { notationView: 'Omega', thresholdN0: 3, constantMultiplier: 1.2, showOverlay: true }
    }
  ];

  var currentStep = 0;
  var lastPanels = [];
  var hoveredPanel = null;

  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  function cScale() { return state.constantMultiplier / DEFAULT_C; }

  /* Curves are tuned to match the source silhouettes at constantMultiplier = 1.5. */
  function thetaUpperBase(x) {
    return 1.65 + 0.06 * x + 2.85 / (1 + Math.exp(-3.3 * (x - 1.35))) +
      4.25 / (1 + Math.exp(-1.9 * (x - 5.1))) - 0.65 * Math.exp(-1.6 * Math.pow(x - 2.6, 2));
  }
  function thetaLowerBase(x) {
    return 0.10 + 0.82 * x - 1.05 / (1 + Math.exp(-3.2 * (x - 3.7))) +
      1.20 / (1 + Math.exp(-2.0 * (x - 5.05)));
  }
  function thetaF(x) {
    return 0.10 + 1.04 * x - 0.24 * x * x / 10 +
      0.70 / (1 + Math.exp(-2.3 * (x - 7.4))) -
      0.72 * Math.exp(-2.0 * Math.pow(x - 4.2, 2));
  }
  function thetaUpper(x) { return thetaUpperBase(x) * cScale(); }
  function thetaLower(x) { return thetaLowerBase(x) * cScale(); }

  function oUpperBase(x) {
    return 1.25 + 0.40 * x + 0.33 * Math.pow(x, 1.55) +
      0.17 * Math.pow(Math.max(0, x - 6.0), 2);
  }
  function oF(x) {
    return 2.45 - 1.55 * Math.exp(-3.8 * Math.pow(x - 1.05, 2)) +
      2.90 * Math.exp(-1.9 * Math.pow(x - 2.45, 2)) -
      1.12 * Math.exp(-0.88 * Math.pow(x - 4.2, 2)) +
      0.41 * x + 0.115 * Math.pow(x, 1.35);
  }
  function oUpper(x) { return oUpperBase(x) * cScale(); }

  function omegaLowerBase(x) {
    return 2.00 + 0.34 * x + 0.28 / (1 + Math.exp(-3.6 * (x - 2.4))) +
      0.50 / (1 + Math.exp(-2.2 * (x - 5.4))) + 0.045 * Math.pow(x, 1.7);
  }
  function omegaF(x) {
    return 1.65 + 1.75 * Math.exp(-2.8 * Math.pow(x - 0.85, 2)) -
      1.70 * Math.exp(-2.5 * Math.pow(x - 2.25, 2)) +
      3.00 / (1 + Math.exp(-3.3 * (x - 3.15))) +
      0.31 * x + 0.035 * x * x;
  }
  function omegaLower(x) { return omegaLowerBase(x) * cScale(); }

  function makePanelGeometry(area, idx) {
    var gap = area.width * 0.105;
    var pw = (area.width - 2 * gap) / 3;
    var left = area.left + idx * (pw + gap);
    var top = area.top + area.height * 0.015;
    var bottom = area.top + area.height * 0.755;
    return {
      left: left,
      top: top,
      width: pw,
      height: bottom - top,
      bottom: bottom,
      xMin: 0,
      xMax: 10,
      yMin: 0,
      yMax: 11.0
    };
  }

  function sx(p, x) {
    return p.left + (x - p.xMin) / (p.xMax - p.xMin) * p.width;
  }

  function sy(p, y) {
    return p.bottom - (y - p.yMin) / (p.yMax - p.yMin) * p.height;
  }

  function drawArrow(ctx, x1, y1, x2, y2, color, lw, scale) {
    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = lw;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
    var a = Math.atan2(y2 - y1, x2 - x1);
    var len = clamp(scale * 0.014, 5, 9);
    var wid = len * 0.58;
    ctx.beginPath();
    ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - len * Math.cos(a) + wid * Math.sin(a), y2 - len * Math.sin(a) - wid * Math.cos(a));
    ctx.lineTo(x2 - len * Math.cos(a) - wid * Math.sin(a), y2 - len * Math.sin(a) + wid * Math.cos(a));
    ctx.closePath();
    ctx.fill();
  }

  function strokeCurve(ctx, p, fn, color, lw) {
    ctx.strokeStyle = color;
    ctx.lineWidth = lw;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    for (var i = 0; i <= 260; i++) {
      var x = p.xMin + (p.xMax - p.xMin) * i / 260;
      var y = clamp(fn(x), -0.3, p.yMax + 1.2);
      var px = sx(p, x), py = sy(p, y);
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();
  }

  function fillAllowed(ctx, p, kind) {
    if (!state.showOverlay) return;
    var x0 = state.thresholdN0;
    ctx.fillStyle = 'rgba(118, 180, 135, 0.20)';
    ctx.beginPath();

    if (kind === 'Theta') {
      for (var i = 0; i <= 150; i++) {
        var x = x0 + (10 - x0) * i / 150;
        if (i === 0) ctx.moveTo(sx(p, x), sy(p, thetaUpper(x)));
        else ctx.lineTo(sx(p, x), sy(p, thetaUpper(x)));
      }
      for (var j = 150; j >= 0; j--) {
        var xb = x0 + (10 - x0) * j / 150;
        ctx.lineTo(sx(p, xb), sy(p, thetaLower(xb)));
      }
    } else if (kind === 'O') {
      ctx.moveTo(sx(p, x0), sy(p, 0));
      ctx.lineTo(sx(p, 10), sy(p, 0));
      for (var k = 150; k >= 0; k--) {
        var xo = x0 + (10 - x0) * k / 150;
        ctx.lineTo(sx(p, xo), sy(p, oUpper(xo)));
      }
    } else {
      for (var m = 0; m <= 150; m++) {
        var xm = x0 + (10 - x0) * m / 150;
        if (m === 0) ctx.moveTo(sx(p, xm), sy(p, omegaLower(xm)));
        else ctx.lineTo(sx(p, xm), sy(p, omegaLower(xm)));
      }
      ctx.lineTo(sx(p, 10), sy(p, p.yMax));
      ctx.lineTo(sx(p, x0), sy(p, p.yMax));
    }
    ctx.closePath();
    ctx.fill();
  }

  function drawViolations(ctx, p, kind, scale) {
    if (!state.showOverlay || state.notationView !== kind) return 0;
    ctx.save();
    ctx.strokeStyle = '#c92525';
    ctx.lineWidth = clamp(scale * 0.002, 1, 1.6);
    var r = clamp(scale * 0.0045, 2, 3.5);
    var count = 0;

    for (var i = 0; i <= 64; i++) {
      var x = state.thresholdN0 + (10 - state.thresholdN0) * i / 64;
      var y, bad = false;
      if (kind === 'Theta') {
        y = thetaF(x);
        bad = y < thetaLower(x) || y > thetaUpper(x);
      } else if (kind === 'O') {
        y = oF(x);
        bad = y > oUpper(x);
      } else {
        y = omegaF(x);
        bad = y < omegaLower(x);
      }
      if (bad) {
        count++;
        var px = sx(p, x), py = sy(p, y);
        ctx.beginPath();
        ctx.moveTo(px - r, py - r);
        ctx.lineTo(px + r, py + r);
        ctx.moveTo(px + r, py - r);
        ctx.lineTo(px - r, py + r);
        ctx.stroke();
      }
    }
    ctx.restore();
    return count;
  }

  function textHalo(ctx, txt, x, y, font, align, baseline, fill, haloWidth) {
    ctx.font = font;
    ctx.textAlign = align || 'left';
    ctx.textBaseline = baseline || 'alphabetic';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = haloWidth == null ? 3 : haloWidth;
    ctx.strokeText(txt, x, y);
    ctx.fillStyle = fill || '#000000';
    ctx.fillText(txt, x, y);
  }

  function dashedThreshold(ctx, p, scale) {
    var x = sx(p, state.thresholdN0);
    ctx.save();
    ctx.setLineDash([clamp(scale * 0.008, 4, 7), clamp(scale * 0.008, 4, 7)]);
    ctx.strokeStyle = '#111111';
    ctx.lineWidth = clamp(scale * 0.0017, 0.8, 1.2);
    ctx.beginPath();
    ctx.moveTo(x, p.bottom);
    ctx.lineTo(x, p.bottom - p.height * 0.315);
    ctx.stroke();
    ctx.restore();
    return x;
  }

  function drawActiveOutline(ctx, p, kind, scale) {
    if (!state.showOverlay || state.notationView !== kind) return;
    ctx.save();
    ctx.strokeStyle = '#74b98b';
    ctx.lineWidth = clamp(scale * 0.0022, 1, 1.6);
    ctx.strokeRect(
      p.left - p.width * 0.025,
      p.top - p.height * 0.012,
      p.width * 1.05,
      p.height * 1.31
    );
    ctx.restore();
  }

  function drawPanel(ctx, p, kind, idx, scale) {
    var active = state.notationView === kind;
    var ink = '#111111';
    var alpha = (state.showOverlay && !active) ? 0.54 : 1;
    var lw = clamp(scale * 0.00145, 0.75, 1.15);
    var serif = clamp(scale * 0.026, 13, 23);
    var capFont = 'italic ' + (serif * 1.08) + 'px Georgia, serif';
    var labelFont = 'italic ' + serif + 'px Georgia, serif';
    var smallFont = 'italic ' + (serif * 0.96) + 'px Georgia, serif';

    ctx.save();
    ctx.globalAlpha = alpha;

    if (active) fillAllowed(ctx, p, kind);

    ctx.strokeStyle = ink;
    ctx.fillStyle = ink;
    ctx.lineWidth = lw;

    ctx.beginPath();
    ctx.moveTo(p.left, p.bottom);
    ctx.lineTo(p.left, p.top);
    ctx.stroke();
    drawArrow(ctx, p.left, p.bottom, p.left + p.width * 1.035, p.bottom, ink, lw, scale);

    var tx = dashedThreshold(ctx, p, scale);
    textHalo(ctx, 'n', p.left + p.width * 1.05, p.bottom + serif * 0.02, labelFont, 'left', 'middle', ink, 2.5);
    textHalo(ctx, 'n₀', tx, p.bottom + serif * 0.90, smallFont, 'center', 'middle', ink, 2.8);

    if (kind === 'Theta') {
      strokeCurve(ctx, p, thetaUpper, ink, lw);
      strokeCurve(ctx, p, thetaF, ink, lw);
      strokeCurve(ctx, p, thetaLower, ink, lw);
      textHalo(ctx, 'c₂g(n)', sx(p, 8.78), sy(p, thetaUpper(8.78)) - serif * 0.52, labelFont, 'left', 'bottom', ink, 3);
      textHalo(ctx, 'f(n)', sx(p, 8.30), sy(p, thetaF(8.30)) - serif * 0.42, labelFont, 'left', 'bottom', ink, 3);
      textHalo(ctx, 'c₁g(n)', sx(p, 7.82), sy(p, thetaLower(7.82)) - serif * 0.18, labelFont, 'left', 'bottom', ink, 3);
      drawViolations(ctx, p, kind, scale);
      textHalo(ctx, 'f(n) = Θ(g(n))', p.left + p.width * 0.62, p.bottom + serif * 1.47, capFont, 'center', 'middle', ink, 3);
      textHalo(ctx, '(a)', p.left + p.width * 0.50, p.bottom + serif * 2.65, 'bold ' + (serif * 0.96) + 'px Georgia, serif', 'center', 'middle', ink, 3);
    } else if (kind === 'O') {
      strokeCurve(ctx, p, oUpper, ink, lw);
      strokeCurve(ctx, p, oF, ink, lw);
      textHalo(ctx, 'cg(n)', sx(p, 9.02), sy(p, oUpper(9.02)) - serif * 0.42, labelFont, 'left', 'bottom', ink, 3);
      textHalo(ctx, 'f(n)', sx(p, 8.55), sy(p, oF(8.55)) - serif * 0.18, labelFont, 'left', 'bottom', ink, 3);
      drawViolations(ctx, p, kind, scale);
      textHalo(ctx, 'f(n) = O(g(n))', p.left + p.width * 0.60, p.bottom + serif * 1.47, capFont, 'center', 'middle', ink, 3);
      textHalo(ctx, '(b)', p.left + p.width * 0.50, p.bottom + serif * 2.65, 'bold ' + (serif * 0.96) + 'px Georgia, serif', 'center', 'middle', ink, 3);
    } else {
      strokeCurve(ctx, p, omegaF, ink, lw);
      strokeCurve(ctx, p, omegaLower, ink, lw);
      textHalo(ctx, 'f(n)', sx(p, 9.22), sy(p, omegaF(9.22)) - serif * 0.30, labelFont, 'left', 'bottom', ink, 3);
      textHalo(ctx, 'cg(n)', sx(p, 9.03), sy(p, omegaLower(9.03)) - serif * 0.14, labelFont, 'left', 'bottom', ink, 3);
      drawViolations(ctx, p, kind, scale);
      textHalo(ctx, 'f(n) = Ω(g(n))', p.left + p.width * 0.62, p.bottom + serif * 1.47, capFont, 'center', 'middle', ink, 3);
      textHalo(ctx, '(c)', p.left + p.width * 0.50, p.bottom + serif * 2.65, 'bold ' + (serif * 0.96) + 'px Georgia, serif', 'center', 'middle', ink, 3);
    }

    ctx.restore();
    drawActiveOutline(ctx, p, kind, scale);
  }

  var asymptoticPlugin = {
    id: 'asymptoticSketch',
    afterDraw: function (chart) {
      var ctx = chart.ctx;
      var W = chart.width;
      var H = chart.height;
      var scale = Math.min(W, H);

      ctx.save();
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, W, H);

      var area = {
        left: W * 0.020,
        top: H * 0.025,
        width: W * 0.958,
        height: H * 0.930
      };

      lastPanels = [
        makePanelGeometry(area, 0),
        makePanelGeometry(area, 1),
        makePanelGeometry(area, 2)
      ];

      drawPanel(ctx, lastPanels[0], 'Theta', 0, scale);
      drawPanel(ctx, lastPanels[1], 'O', 1, scale);
      drawPanel(ctx, lastPanels[2], 'Omega', 2, scale);

      ctx.restore();
    }
  };

  var chart = new Chart(canvas.getContext('2d'), {
    type: 'scatter',
    data: { datasets: [] },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      scales: {
        x: { display: false, min: 0, max: 1 },
        y: { display: false, min: 0, max: 1 }
      },
      events: []
    },
    plugins: [asymptoticPlugin]
  });
  window.__markRendered();

  function redraw() {
    chart.update('none');
  }

  window.update_notationView = function (v) {
    state.notationView = v;
    state.showOverlay = true;
    var ov = document.getElementById('showOverlayInput');
    if (ov) ov.checked = true;
    redraw();
  };

  window.update_thresholdN0 = function (v) {
    state.thresholdN0 = v;
    redraw();
  };

  window.update_constantMultiplier = function (v) {
    state.constantMultiplier = v;
    var out = document.getElementById('constantMultiplierVal');
    if (out) out.value = (+v).toFixed(1).replace(/\.0$/, '');
    redraw();
  };

  window.toggle_showOverlay = function (on) {
    state.showOverlay = !!on;
    redraw();
  };

  function setControlValues(st) {
    state.notationView = st.notationView;
    state.thresholdN0 = +st.thresholdN0;
    state.constantMultiplier = +st.constantMultiplier;
    state.showOverlay = !!st.showOverlay;

    var sel = document.getElementById('notationViewInput');
    var n0 = document.getElementById('thresholdN0Input');
    var c = document.getElementById('constantMultiplierInput');
    var ov = document.getElementById('showOverlayInput');
    if (sel) sel.value = state.notationView;
    if (n0) n0.value = state.thresholdN0;
    if (c) c.value = state.constantMultiplier;
    if (ov) ov.checked = state.showOverlay;

    var n0v = document.getElementById('thresholdN0Val');
    var cv = document.getElementById('constantMultiplierVal');
    if (n0v) n0v.value = state.thresholdN0;
    if (cv) cv.value = state.constantMultiplier.toFixed(1).replace(/\.0$/, '');
    redraw();
  }

  function showStep(i) {
    currentStep = (i + steps.length) % steps.length;
    setControlValues(steps[currentStep].state);
    var narr = document.getElementById('demoNarration');
    var lab = document.getElementById('stepLabel');
    if (narr) narr.textContent = steps[currentStep].narration;
    if (lab) lab.textContent = (currentStep + 1) + ' / ' + steps.length;
  }

  window.prevStep = function () { showStep(currentStep - 1); };
  window.nextStep = function () { showStep(currentStep + 1); };

  canvas.addEventListener('mousemove', function (e) {
    var rect = canvas.getBoundingClientRect();
    var x = (e.clientX - rect.left) * chart.width / rect.width;
    var y = (e.clientY - rect.top) * chart.height / rect.height;
    var names = [
      'Θ: after n₀, f(n) is trapped between lower and upper constant multiples of g(n).',
      'O: after n₀, f(n) only has to stay below one constant multiple of g(n).',
      'Ω: after n₀, f(n) only has to stay above one constant multiple of g(n).'
    ];

    hoveredPanel = null;
    for (var i = 0; i < lastPanels.length; i++) {
      var p = lastPanels[i];
      if (x >= p.left && x <= p.left + p.width * 1.06 && y >= p.top && y <= p.bottom + p.height * 0.34) {
        hoveredPanel = i;
        break;
      }
    }

    if (hoveredPanel == null) {
      canvas.style.cursor = 'default';
      hideTooltip();
    } else {
      canvas.style.cursor = 'pointer';
      showTooltip(names[hoveredPanel] + ' Turn on the overlay to see exactly which side of the bound is being checked.', e);
    }
  });

  canvas.addEventListener('mouseleave', function () {
    hoveredPanel = null;
    canvas.style.cursor = 'default';
    hideTooltip();
  });

