    var v = canvasToVirtual(e);
    hoveredPanel = null;
    for (var i = 0; i < lastHitPanels.length; i++) {
      var h = lastHitPanels[i];
      if (v.x >= h.left && v.x <= h.right && v.y >= h.top && v.y <= h.bottom) {
