    }
  });

  canvas.addEventListener('mouseleave', function () {
    hoveredPanel = null;
    canvas.style.cursor = 'default';
    hideTooltip();
  });

  canvas.addEventListener('click', function () {
    if (hoveredPanel == null) return;
    var titles = ['Theta bound', 'Big-O bound', 'Big-Omega bound'];
    var bodies = [
      'Θ(g(n)) is a two-sided eventual comparison. After n₀, f(n) must remain between c₁g(n) and c₂g(n), while crossings near the origin are ignored.',
      'O(g(n)) is an eventual upper bound. f(n) may wiggle or be far below the comparison curve, as long as some positive constant multiple of g(n) is above it after n₀.',
      'Ω(g(n)) is an eventual lower bound. After n₀, f(n) must be at least a positive constant multiple of g(n), but it need not equal g(n).'
    ];
